async sweepProtocolFeeInstruction({
    payer,
    poolKey,
    pool,
    quoteTokenProgram,
    globalConfig
  }) {
    return this.offlineProgram.methods.sweepProtocolFee().accountsStrict(
      this.sweepFeeAccounts(
        payer,
        poolKey,
        pool,
        quoteTokenProgram,
        getFeeRecipient(globalConfig, pool.isMayhemMode)
      )
    ).instruction();
  }

